       toast('Google Play','info','Aktuell wurde kein offener, bereits bezahlter Kauf gefunden.');
     }
     return recovered;
   }catch(e){
     console.warn('V7.273 pending lookup',e);
     return 0;
   }finally{
     recoveryBusy=false;
